when JSON_REQUEST {
    set rootval [JSON::root]
    JSON::set $rootval string HelloWorld
    set rendered [JSON::render $cache]
}
when HTTP_REQUEST_DATA {
    set cache [JSON::create]
    set rootval [JSON::root $cache]
    JSON::set $rootval string HelloWorld
    set rendered [JSON::render $cache]
}
